def wrap_query(query: str, variant: int = 0) -> str:
    """
    Embeds the query into a system log parsing template.
    
    Args:
        query: The harmful request to embed
        variant: Template variant (0-3)
    
    Returns:
        Complete attack prompt with query embedded as historical log data
    """
    # Escape double quotes in query to prevent breaking the log format
    escaped_query = query.replace('"', '\\"')
    
    # Generate pseudo-random but deterministic index based on query hash
    idx = abs(hash(query)) % 100000
    
    # Select template variant (cycle if out of range)
    template = TEMPLATE_VARIANTS[variant % len(TEMPLATE_VARIANTS)]
    
    # Embed query into template
    return template.format(query=escaped_query, idx=idx)


